/**
 * Abugram: the ad card at the top of a chat (private chats, groups, bots and channels), under the chat header.
 * It is the same card as at the top of the chat list (lib/abugram/ads), and is counted the same way.
 */
import {mountAbugramAdCard} from '@lib/abugram/ads';

let mounted: {chatId: number, el: HTMLElement};

export function mountChatAd(chat: any, peerId: any, managers: any) {
  if(mounted) {
    mounted.el.remove();
    mounted = undefined;
  }
  // * inside the messages, at the very top: the same place as Telegram's own sponsored message, so it is never hidden
  // * under the header, and it scrolls with the chat
  const inner: HTMLElement = (chat as any).bubbles?.chatInner;
  if(!inner) return;
  const el = document.createElement('div');
  el.className = 'abugram-chat-ad-host';
  inner.prepend(el);
  mounted = {chatId: 0, el};
  // * the card sticks below everything that covers the top of the chat: the header, the pinned-message plate and the
  // * floating media player (a fixed or absolute bar over the chat). Measured, since the plate and the player come and go
  const topbar: HTMLElement = (chat as any).topbar?.container;
  const column: HTMLElement = topbar?.closest('#column-center') || topbar?.parentElement;
  const coverBottom = () => {
    let bottom = topbar ? topbar.getBoundingClientRect().bottom : 0;
    if(column) {
      const colTop = column.getBoundingClientRect().top;
      for(const node of Array.from(column.querySelectorAll<HTMLElement>('*'))) {
        if(node === el || el.contains(node) || topbar?.contains(node)) continue;
        const pos = getComputedStyle(node).position;
        if(pos !== 'fixed' && pos !== 'absolute' && pos !== 'sticky') continue;
        const r = node.getBoundingClientRect();
        if(r.height > 0 && r.top <= colTop + 160 && r.bottom > bottom && r.bottom < colTop + 200) bottom = r.bottom;
      }
    }
    const base = column ? column.getBoundingClientRect().top : 0;
    return Math.max(0, bottom - base);
  };
  const pin = () => {
    el.style.top = coverBottom() + 'px';
  };
  pin();
  const timer = setInterval(() => {
    if(!el.isConnected) {
      clearInterval(timer);
      return;
    }
    pin();
  }, 500);
  mountAbugramAdCard(el, 'chat');
  // * the messages are drawn after the chat is opened and can clear the top: put the card back if they did
  for(const delay of [600, 1800]) {
    setTimeout(() => {
      if(!el.isConnected && inner.isConnected) inner.prepend(el);
    }, delay);
  }
}
